<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch,nextTick} from 'vue';
import XmlEditor from './XmlEditor.vue';import Diagram from './Diagram.vue';
import {api,type Model} from './api';import {scxmlTemplate,bpmnTemplate} from './templates';
const tab=ref('models'),models=ref<Model[]>([]),selectedId=ref(''),xml=ref(''),editor=ref<InstanceType<typeof XmlEditor>>();
const error=ref(''),notice=ref(''),busy=ref(false),connection=ref(false),selectedNode=ref(''),diagnostics=ref<any[]>([]),validation=ref<any>(null);
const previewXml=ref('');const previewError=ref(''),previewStale=ref(false),validatedXml=ref(''),savedXml=ref(''),version=ref('draft'),filter=ref('all');
const trial=ref<any>(null),trialAction=ref(''),trialParameters=ref('{}'),trialEvent=ref(''),trialAuto=ref(false),trialDelay=ref(500);
const config=ref<any>({entry:'emission_task_lifecycle',processes:[],devices:[],autoComplete:true,variables:{commandTimeout:'PT15M',workflowTimeout:'PT45M'}});
const conditionsText=ref('{}');const bindingsText=ref('{}'),variablesText=ref('{"commandTimeout":"PT15M","workflowTimeout":"PT45M"}');
const currentRun=ref<any>(null);const runs=ref<any[]>([]),runId=ref(''),iframe=ref<HTMLIFrameElement>(),newDialog=ref<HTMLDialogElement>(),newName=ref(''),newKind=ref<'scxml'|'bpmn'>('scxml');
const trialView=ref('history');let previewTimer:ReturnType<typeof setTimeout>,saveTimer:ReturnType<typeof setTimeout>,poll:ReturnType<typeof setInterval>,validateTicket=0;
const model=computed(()=>models.value.find(m=>m.id===selectedId.value));const currentRevision=computed(()=>model.value?.revisions.at(-1));
const scxmlModels=computed(()=>models.value.filter(m=>m.kind==='scxml'));const bpmnModels=computed(()=>models.value.filter(m=>m.kind==='bpmn'));
const visibleModels=computed(()=>models.value.filter(m=>filter.value==='all'||m.kind===filter.value));
const draftChanged=computed(()=>savedXml.value!==xml.value);
const canTrial=computed(()=>validation.value?.valid&&validatedXml.value===xml.value&&model.value?.kind==='scxml');
const trialMatches=computed(()=>trial.value?.xml===xml.value);
const diagramState=computed(()=>trialMatches.value?trial.value?.snapshot.state_id:undefined);
const availableActions=computed(()=>trial.value?.availableActions||[]);
const availableEvents=computed(()=>Object.entries(trial.value?.capabilities.confirmations||{}).filter(([,c]:any)=>(c.source_outer||[]).includes(trial.value?.snapshot.outer_state)));
function fail(e:any){error.value=e.message||String(e);}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){fail(e);}finally{busy.value=false;}}
function latest(m:Model){return m.revisions.at(-1)?.id||'';}
function revisionLabel(id:string){return id?id.slice(0,8):'未保存版本';}
async function refreshModels(){models.value=await api('/workbench/models');}
function selectModel(id:string){clearTimeout(saveTimer);if(model.value&&draftChanged.value)void persist(model.value,xml.value).catch(fail);selectedId.value=id;const chosen=models.value.find(m=>m.id===id)!;xml.value=chosen.draft;previewXml.value=chosen.draft;savedXml.value=chosen.draft;version.value='draft';selectedNode.value='';trial.value=null;validation.value=null;diagnostics.value=[];previewError.value='';queueValidation();}
function edit(value:string){xml.value=value;version.value='draft';previewStale.value=true;queueValidation();clearTimeout(saveTimer);const current=model.value;if(current)saveTimer=setTimeout(()=>persist(current,value).catch(fail),1400);}
const saveQueues=new Map<string,Promise<any>>();
async function persist(current:Model,value:string){const previous=saveQueues.get(current.id)||Promise.resolve();const pending=previous.catch(()=>{}).then(()=>persistNow(current,value));saveQueues.set(current.id,pending);return pending;}
async function persistNow(current:Model,value:string){const saved=await api('/workbench/models',{id:current.id,name:current.name,kind:current.kind,xml:value});const index=models.value.findIndex(m=>m.id===current.id);if(index>=0)models.value[index]=saved;if(selectedId.value===current.id&&xml.value===value)savedXml.value=value;}
function queueValidation(){clearTimeout(previewTimer);const ticket=++validateTicket;previewTimer=setTimeout(()=>{previewXml.value=xml.value;validate(ticket);},650);}
async function validate(ticket=++validateTicket){const current=model.value;if(!current)return;const value=xml.value;try{const result=await api('/workbench/validate',{kind:current.kind,xml:value});if(ticket!==validateTicket||current.id!==selectedId.value||value!==xml.value)return;validation.value=result;diagnostics.value=result.diagnostics;validatedXml.value=value;}catch(e){if(ticket===validateTicket)fail(e);}}
async function saveVersion(){const current=model.value;if(!current)return;clearTimeout(saveTimer);await persist(current,xml.value);const revision=await api('/workbench/models/'+current.id+'/versions',{});await refreshModels();if(selectedId.value===current.id)version.value=revision.id;notice.value='已保存不可变版本 '+revisionLabel(revision.id);await validate();}
function chooseVersion(){if(!model.value)return;const value=version.value==='draft'?model.value.draft:model.value.revisions.find(r=>r.id===version.value)?.xml;if(value!==undefined){xml.value=value;queueValidation();previewStale.value=true;}}
function exportXml(){const blob=new Blob([xml.value],{type:'application/xml'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=model.value?.name||'model.xml';link.click();URL.revokeObjectURL(url);}
async function createModel(){const name=newName.value.trim();if(!name)throw Error('请输入文件名');const saved=await api('/workbench/models',{name,kind:newKind.value,xml:newKind.value==='scxml'?scxmlTemplate:bpmnTemplate});await refreshModels();selectModel(saved.id);newDialog.value?.close();}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await action(async()=>{const value=await file.text();const doc=new DOMParser().parseFromString(value,'application/xml');const kind=doc.documentElement.localName==='scxml'?'scxml':'bpmn';const saved=await api('/workbench/models',{name:file.name,kind,xml:value});await refreshModels();selectModel(saved.id);});input.value='';}
async function createTrial(){trial.value=await api('/workbench/trials',{xml:xml.value});trialAction.value=trial.value.availableActions[0]||'';trialEvent.value=Object.keys(trial.value.capabilities.confirmations)[0]||'';notice.value='已创建独立试运行，上一轮记录保留在本地数据目录';}
async function trialCommand(){const session=trial.value.id;const value=await api('/workbench/trials/'+session+'/commands',{action:trialAction.value,parameters:JSON.parse(trialParameters.value)});trial.value=value;trialAction.value=value.availableActions[0]||'';if(trialAuto.value&&value.snapshot.active_command_id){const command=value.snapshot.active_command_id;setTimeout(()=>{if(trial.value?.id===session&&trial.value.snapshot.active_command_id===command)action(()=>trialComplete('success'));},trialDelay.value);}}
async function trialComplete(outcome:string){trial.value=await api('/workbench/trials/'+trial.value.id+'/simulate',{command_id:trial.value.snapshot.active_command_id,outcome});trialAction.value=trial.value.availableActions[0]||'';}
async function injectTrial(){const confirmation=trial.value.capabilities.confirmations[trialEvent.value];trial.value=await api('/workbench/trials/'+trial.value.id+'/events',{event_id:crypto.randomUUID(),event:trialEvent.value,observed_outer_state:confirmation.observation});trialAction.value=trial.value.availableActions[0]||'';}
function addDevice(){const first=scxmlModels.value.find(m=>m.revisions.length);if(!first)return;config.value.devices.push({model:first.id,revision:latest(first),component:'demo',count:1,autoComplete:true,delayMs:500});}
function modelFor(id:string){return models.value.find(m=>m.id===id);}
function setDeviceModel(row:any){row.revision=latest(modelFor(row.model)!);}
function processSelection(id:string){return config.value.processes.find((p:any)=>p.model===id);}
function setProcessVersion(id:string,revision:string){config.value.processes=config.value.processes.filter((p:any)=>p.model!==id);if(revision)config.value.processes.push({model:id,revision});}
function readConfig(){return {...config.value,bindings:JSON.parse(bindingsText.value),variables:JSON.parse(variablesText.value),conditions:JSON.parse(conditionsText.value)};}
async function saveConfig(){config.value=await api('/workbench/configuration',readConfig());notice.value='联调配置已保存';}
async function applyConfig(){config.value=await api('/workbench/environment',readConfig());notice.value='模拟环境已应用，设备从所选模型的初始状态启动';await pollConnection();}
async function startRun(){const current=readConfig();const run=await api('/workbench/runs',current);runId.value=run.id;tab.value='runs';await refreshRuns();}
async function refreshRuns(){runs.value=await api('/runs');if(runId.value)currentRun.value=await api('/runs/'+encodeURIComponent(runId.value));}
async function stopRun(){currentRun.value=await api('/runs/'+encodeURIComponent(runId.value)+'/stop',{});notice.value='流程已停止，设备已受理动作仍由组件端完成';await refreshRuns();}
async function pollConnection(){try{connection.value=(await api('/connection')).connected;}catch{connection.value=false;}}
function switchTab(value:string){tab.value=value;if(value==='runs')refreshRuns().catch(fail);}
async function useDefaults(){config.value={entry:'emission_task_lifecycle',processes:bpmnModels.value.map(m=>({model:m.id,revision:latest(m)})),devices:scxmlModels.value.filter(m=>['seed-source-state-machine','shg-injection-state-machine','preamp-state-machine','multipass-state-machine'].includes(m.id)).map(m=>({model:m.id,revision:latest(m),component:m.id.startsWith('seed')?'seed':m.id.startsWith('shg')?'shg':m.id.startsWith('preamp')?'preamp':'multipass',count:1,autoComplete:true,delayMs:500})),autoComplete:true};bindingsText.value=JSON.stringify({sourceTargets:['seed_01']},null,2);variablesText.value=JSON.stringify({commandTimeout:'PT15M',workflowTimeout:'PT45M'},null,2);}
onMounted(async()=>{await action(async()=>{await refreshModels();const saved=await api('/workbench/configuration');if(saved.entry){config.value=saved;bindingsText.value=JSON.stringify(saved.bindings||{},null,2);variablesText.value=JSON.stringify(saved.variables||{},null,2);conditionsText.value=JSON.stringify(saved.conditions||{},null,2);}else await useDefaults();const first=models.value.find(m=>m.id==='seed-source-state-machine')||models.value[0];if(first)selectModel(first.id);await refreshRuns();runId.value=runs.value[0]?.id||'';await pollConnection();});poll=setInterval(()=>{pollConnection();if(tab.value==='runs'&&runId.value)api('/runs/'+encodeURIComponent(runId.value)).then(r=>currentRun.value=r).catch(fail);},3000);});
onBeforeUnmount(()=>{clearTimeout(previewTimer);clearTimeout(saveTimer);clearInterval(poll);});
watch(availableEvents,events=>{if(!events.some(([key])=>key===trialEvent.value))trialEvent.value=String(events[0]?.[0]||'');});
watch(runId,()=>refreshRuns().catch(fail));
watch(()=>tab.value,async()=>{await nextTick();window.dispatchEvent(new Event('resize'));});
</script>

<template>
 <header class="app-header"><a class="brand" href="/workbench/"><span class="brand-mark">C</span><span><b>CDI8 WORKBENCH</b><small>流程与状态机 · 开发联调</small></span></a>
  <nav aria-label="工作区"><button :class="{active:tab==='models'}" @click="switchTab('models')">模型开发</button><button :class="{active:tab==='config'}" @click="switchTab('config')">联调配置</button><button :class="{active:tab==='runs'}" @click="switchTab('runs')">运行调试</button></nav>
  <span class="connection"><i :class="{online:connection}"></i>{{connection?'Tango 已连接':'Tango 未连接'}}</span>
 </header>
 <div v-if="error" class="message error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="message success" role="status">{{notice}}<button @click="notice=''">关闭</button></div>
 <main v-show="tab==='models'" class="development">
  <aside class="model-sidebar"><div class="sidebar-title"><h2>项目模型</h2><button title="新建模型" aria-label="新建模型" @click="newName='';newDialog?.showModal()">＋</button></div><div class="model-filters"><button v-for="item in [['all','全部'],['bpmn','流程'],['scxml','状态机']]" :class="{active:filter===item[0]}" @click="filter=item[0]">{{item[1]}}</button></div>
   <button v-for="item in visibleModels" :key="item.id" class="model-item" :class="{selected:item.id===selectedId}" @click="selectModel(item.id)"><span class="file-icon" :class="item.kind">{{item.kind==='bpmn'?'B':'S'}}</span><span><b>{{item.name}}</b><small>{{item.kind.toUpperCase()}} · {{item.revisions.length}} 个版本</small></span></button>
   <label class="import-model">导入 XML 文件<input type="file" accept=".xml,.scxml,.bpmn,.bpmn20.xml" @change="importFile"></label>
   <p class="sidebar-help">草稿自动保存。保存版本后，可在联调配置中绑定和运行。</p>
  </aside>
  <section v-if="model" class="model-workspace">
   <div class="workspace-toolbar"><div><span class="eyebrow">{{model.kind.toUpperCase()}} / MODEL</span><h1>{{model.name}}<span class="draft-dot" v-if="draftChanged"> · 保存中</span></h1></div><div class="toolbar-actions"><select aria-label="模型版本" v-model="version" @change="chooseVersion"><option value="draft">当前草稿</option><option v-for="r in model.revisions.slice().reverse()" :value="r.id">版本 {{revisionLabel(r.id)}} · {{new Date(r.created).toLocaleString()}}</option></select><button :disabled="busy" @click="action(()=>validate())">校验</button><button @click="exportXml">导出</button><button class="primary" :disabled="busy" @click="action(saveVersion)">保存版本</button></div></div>
   <div class="editing-grid"><section class="editor-panel"><div class="panel-heading"><span>XML 源码</span><small>自动保存草稿</small></div><XmlEditor ref="editor" :value="xml" :diagnostics="diagnostics" @change="edit" @select="selectedNode=$event" /></section>
    <section class="preview-panel"><div class="panel-heading"><span>实时预览</span><small :class="{bad:previewError}">{{previewError?'保留上次有效预览':previewStale?'正在更新…':'与当前 XML 一致'}}</small></div><Diagram :kind="model.kind" :xml="previewXml" :state="diagramState" :selected="selectedNode" @select="selectedNode=$event;editor?.reveal($event)" @error="previewError=$event;previewStale=true" @ready="previewError='';previewStale=false" /><div v-if="previewError" class="preview-warning">{{previewError}}</div><div class="preview-caption">滚轮缩放 · 拖动平移 · 点击节点定位 XML</div></section>
   </div>
   <section class="development-bottom"><div class="bottom-tabs"><button :class="{active:trialView==='history'}" @click="trialView='history'">{{model.kind==='scxml'?'组件试运行':'模型校验'}}</button><button :class="{active:trialView==='diagnostics'}" @click="trialView='diagnostics'">校验结果 <span class="count">{{diagnostics.length}}</span></button><span class="validation-state" :class="{bad:validation&&!validation.valid}">{{!validation?'正在校验…':validatedXml!==xml?'内容已变化，等待校验':validation.valid?'执行校验通过':'执行校验未通过'}}</span></div>
    <div v-if="trialView==='diagnostics'||model.kind==='bpmn'" class="diagnostics"><p v-if="!diagnostics.length">{{validation?.valid?'当前模型已通过结构与执行能力校验。设备动作和集合绑定将在联调启动前进一步检查。':'正在检查模型…'}}</p><button v-for="(d,i) in diagnostics" @click="d.elementId&&editor?.reveal(d.elementId)">{{i+1}}. {{d.line?'第 '+d.line+' 行：':''}}{{d.elementId?d.elementId+'：':''}}{{d.message}}</button><p v-if="model.kind==='scxml'" class="muted">当前支持层级状态、初始状态与单目标事件迁移；不支持 parallel、cond 和可执行内容。</p></div>
    <div v-else class="trial-panel"><div class="trial-controls"><div class="trial-title"><div><strong>独立设备试验</strong><small>{{trial?'实例 '+trial.id.slice(0,8):'用当前有效模型创建独立实例'}}</small></div><button :disabled="!canTrial||busy" @click="action(createTrial)">{{trial?'重新试验':'创建试运行'}}</button></div>
     <template v-if="trial"><p v-if="!trialMatches" class="inline-warning">模型已修改；当前实例仍运行创建时的版本。重新试验可加载新内容。</p><div class="trial-state"><span>当前状态</span><b>{{trial.snapshot.outer_state_label}} / {{trial.snapshot.inner_state_label}}</b></div><label>动作<select v-model="trialAction"><option v-for="a in availableActions" :value="a">{{trial.capabilities.actions[a].label}} · {{a}}</option></select></label><label>参数 JSON<input v-model="trialParameters" spellcheck="false"></label><div class="trial-auto"><label><input type="checkbox" v-model="trialAuto">自动成功反馈</label><input aria-label="试运行自动反馈延迟" type="number" min="0" max="3600000" v-model="trialDelay"><small>ms</small></div><button class="primary" :disabled="busy||!trialAction||!!trial.snapshot.active_command_id" @click="action(trialCommand)">发送动作请求</button><div v-if="trial.snapshot.active_command_id" class="feedback"><span>等待反馈 · {{trial.snapshot.active_action}}</span><button @click="action(()=>trialComplete('success'))" :disabled="busy">成功</button><button class="danger" @click="action(()=>trialComplete('failure'))" :disabled="busy">失败</button></div><div v-if="availableEvents.length" class="inject-event"><select aria-label="外部确认事件" v-model="trialEvent"><option v-for="[key,c] in availableEvents" :value="key">{{(c as any).label}}</option></select><button :disabled="busy||!trialEvent" @click="action(injectTrial)">注入确认事件</button></div></template>
    </div><div class="trial-history"><div class="panel-heading"><span>状态迁移记录</span><small>{{trial?.history.length||0}} 条</small></div><table v-if="trial?.history.length"><thead><tr><th>时间</th><th>事件</th><th>源 → 目标</th></tr></thead><tbody><tr v-for="event in trial.history.slice().reverse()"><td>{{event.occurred_at?.slice(11,23)}}</td><td>{{event.event}}</td><td>{{event.source}} → {{event.target}}</td></tr></tbody></table><div v-else class="empty-state">创建试运行并发送动作请求，观察命令与状态迁移。</div></div></div>
   </section>
  </section>
 </main>
 <main v-show="tab==='config'" class="configuration-page">
  <div class="page-heading"><div><span class="eyebrow">SIMULATION CONFIGURATION</span><h1>配置一次可重复的联调</h1><p>固定流程和状态机版本，创建模拟实例，再绑定流程中的设备集合。</p></div><div class="toolbar-actions"><button @click="action(useDefaults)">载入四组件示例</button><button :disabled="busy" @click="action(saveConfig)">保存配置</button><button class="primary" :disabled="busy" @click="action(applyConfig)">{{busy?'处理中…':'应用模拟环境'}}</button></div></div>
  <div class="configuration-grid"><section class="config-card"><h2><span>01</span> 流程与依赖版本</h2><label>入口流程<select v-model="config.entry"><option v-for="m in bpmnModels" :value="m.id">{{m.name}}</option></select></label><div class="process-revisions"><label v-for="m in bpmnModels"><span>{{m.name}}</span><select :aria-label="m.name+'版本'" :value="processSelection(m.id)?.revision||''" @change="setProcessVersion(m.id,($event.target as HTMLSelectElement).value)"><option value="">不参与本配置</option><option v-for="r in m.revisions.slice().reverse()" :value="r.id">{{revisionLabel(r.id)}} · {{new Date(r.created).toLocaleString()}}</option></select></label></div><p class="hint">入口和调用的子流程都需选择版本。启动时固定依赖，运行中保存的新版本不会替换它们。</p></section>
  <section class="config-card"><div class="card-heading"><h2><span>02</span> 模拟设备实例</h2><button @click="addDevice">＋ 添加组件</button></div><div v-for="(row,i) in config.devices" class="device-config"><div class="device-config-head"><b>组件 {{Number(i)+1}}</b><button @click="config.devices.splice(i,1)" aria-label="移除组件">移除</button></div><div class="device-fields"><label>SCXML 模型<select v-model="row.model" @change="setDeviceModel(row)"><option v-for="m in scxmlModels" :value="m.id">{{m.name}}</option></select></label><label>固定版本<select v-model="row.revision"><option v-for="r in modelFor(row.model)?.revisions.slice().reverse()" :value="r.id">{{revisionLabel(r.id)}}</option></select></label><label>组件类型<input v-model="row.component" placeholder="例如 seed 或 demo"></label><label>实例数量<input type="number" min="1" max="200" v-model.number="row.count"></label><label class="checkbox"><input type="checkbox" v-model="row.autoComplete">自动成功反馈</label><label>反馈延迟 / ms<input type="number" min="0" max="3600000" v-model.number="row.delayMs"></label></div><small>实例编号：{{row.component}}_01{{row.count>1?' … '+row.component+'_'+String(row.count).padStart(2,'0'):''}}</small></div><label class="checkbox"><input type="checkbox" v-model="config.autoComplete">同步条件设备的命令自动完成</label><p class="hint">应用环境会为全部实例创建一个新的 Tango Device Server，设备从模型初始状态开始；外部条件默认未满足，可显式配置初始值。</p></section>
  <section class="config-card"><h2><span>03</span> 设备集合绑定</h2><textarea aria-label="设备集合绑定 JSON" v-model="bindingsText" spellcheck="false"></textarea><p class="hint">自动生成 allComponents、contextTargets 和各类型的 xxxTargets。这里可显式覆盖，例如 <code>{"sourceTargets":["seed_01"]}</code>。</p></section>
  <section class="config-card"><h2><span>04</span> 流程初始变量</h2><textarea aria-label="流程初始变量 JSON" v-model="variablesText" spellcheck="false"></textarea><p class="hint">支持动作与流程超时、光源选择等参数。设备实例与版本信息由平台记录。</p><label class="conditions-config">外部条件定义 / 初始值 JSON<textarea aria-label="外部条件定义 JSON" v-model="conditionsText" spellcheck="false"></textarea></label><p class="hint">可定义额外条件，例如 {"alignment_ready":false}，由流程的 lab:condition 引用。</p></section></div>
  <div class="configuration-footer"><span>{{config.environment?'已应用环境 '+config.environment.id.slice(0,8):'尚未应用模拟环境'}} · 应用后再启动</span><button class="primary" :disabled="busy||!config.environment" @click="action(startRun)">启动联调流程 →</button></div>
 </main>
 <main v-if="tab==='runs'" class="run-page"><div class="run-toolbar"><div><span class="eyebrow">LIVE DEBUGGING</span><h1>流程与设备联动</h1></div><div class="toolbar-actions"><select aria-label="联调运行记录" v-model="runId"><option value="">最新运行 / 流程定义</option><option v-for="r in runs" :value="r.id">{{r.name}} · {{new Date(r.started).toLocaleString()}}</option></select><button @click="action(refreshRuns)">刷新记录</button><button :disabled="busy||!currentRun||currentRun.ended" class="danger" @click="action(stopRun)">停止流程</button><button @click="tab='config'">配置下一次运行</button></div></div><iframe ref="iframe" class="runtime-frame" :key="runId" :src="'/runtime.html?embedded=1'+(runId?'&run='+encodeURIComponent(runId):'')" title="流程和设备联动总览"></iframe></main>
 <dialog ref="newDialog" class="new-dialog"><form @submit.prevent="action(createModel)"><div class="card-heading"><h2>新建模型</h2><button type="button" @click="newDialog?.close()">关闭</button></div><label>模型类型<select v-model="newKind"><option value="scxml">SCXML 状态机</option><option value="bpmn">BPMN 流程</option></select></label><label>文件名<input v-model="newName" required :placeholder="newKind==='scxml'?'demo.scxml':'demo.bpmn20.xml'"></label><p class="hint">从可执行的最小示例开始编辑。创建后保存版本，再到联调配置中选择。</p><button class="primary" :disabled="busy">创建模型</button></form></dialog>
</template>
